#include <vector>
#include <type_traits>

int main() {
    std::vector<int> vi(1);
    std::vector<bool> vb(1);

    // Standard vector reference is T&
    using IntRef = std::vector<int>::reference;
    // std::is_same_v<IntRef, int&> is true

    // vector<bool> reference is a proxy object (not bool&)
    using BoolRef = std::vector<bool>::reference;
    // std::is_same_v<BoolRef, bool&> is false

    // Demonstration of proxy behavior
    vb[0] = true; // Uses proxy assignment
    bool b = vb[0]; // Uses proxy conversion to bool

    return 0;
}
